import RNA, random, multiprocessing as mp, time
target = "(((.(..((.((....)).((....)).))..).(....).)))"
def fold(s): return RNA.fold_compound(s).mfe()[0]
def worker(seed):
    random.seed(seed)
    best=None;bd=99
    for _ in range(500):
        start=''.join(random.choice('ACGU') for _ in range(44))
        seq,d=RNA.inverse_fold(start,target)
        if d==0 and fold(seq)==target:
            return seq
        if d<bd: bd=d; best=seq
    return (bd,best)
if __name__=='__main__':
    with mp.Pool(48) as p:
        results=[]
        for r in p.imap_unordered(worker,range(800)):
            if isinstance(r,str):
                print('SOLVED',r); p.terminate(); break
            results.append(r)
        else:
            results.sort()
            print('best dist',results[0] if results else 'none')
EOF
